        'Status': '',
        'RawLimits': ts.PropObj({'Nominal': 100, 'Low': 9, 'High': 11}),
      }),
      ts.PropObj({
        'Limits': ts.PropObj({
          'ThresholdType': 'PERCENTAGE',
          'Nominal': 100,
          'Low': 990,
          'High': 1010,
          'ThresholdTypeExpr': '',
          'NominalExpr': '',
          'LowExpr': '',
          'HighExpr': '',
          'UseThresholdTypeExpr': false,
